sksl:
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float amount;
uniform float width;
uniform float angle;
uniform float center;
uniform float mirrorEdges;

float2 turn(float2 p,float a){float c=cos(a),s=sin(a);return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float4 readLayer(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);float2 s=((fromLayer * float3(uv * layer,1.0)).xy / size);if(s.x<0.0||s.y<0.0||s.x>1.0||s.y>1.0)return float4(0.0);return float4(image.eval(s * size));}
float2 borderUV(float2 uv,float mirrorEdges){return mirrorEdges>.5?1.0-abs(mod(uv,2.0)-1.0):uv;}
float light(float4 c){return c.a>.00001?dot(c.rgb/c.a,float3(.2126,.7152,.0722)):0.0;}

half4 main(float2 coord){float2 tmLocalSize=max(layer,float2(1.0));float unit=min(tmLocalSize.x,tmLocalSize.y),a=angle*.01745329252;float2 q=turn((((toLayer * float3(coord,1.0)).xy / layer)-.5)*tmLocalSize/unit,-a);float d=(q.y-center)/max(width,.001),weight=exp(-d*d*2.0);q.x/=max(.05,1.0+amount*weight);return readLayer(borderUV(turn(q,a)*unit/tmLocalSize+.5,mirrorEdges));}
